import { Link, useLocation } from "react-router-dom";

function NavBar() {
    const location = useLocation();
    const currentPath = location.pathname;

    return(
        // <nav className="navbar bodoni-moda-serif fixed-top">
        //     <div className="container-fluid">

        //         <div className="navbar-links d-flex justify-content-center align-items-center gap-2 mx-auto">

        //             <Link to="/" className={currentPath==='/' ? 'active':''}>Home</Link>
        //             <Link to="/portrait" className={currentPath==='/portrait' ? 'active':''}>Portrait</Link>
        //             <Link to="/event/wedding" className={currentPath==='/event/wedding' ? 'active':''}>Wedding</Link>
        //             <Link to="/event/concert" className={currentPath==='/event/concert' ? 'active':''}>Concert</Link>
        //             <div className = "navbar-brand mb-3">
        //                 <img src={'/logo.png'} alt="Logo" height="30"/>
        //             </div>
        //             <Link to="/event/travel" className={currentPath==='/event/travel' ? 'active':''}>Travel</Link>
        //             <Link to="/event/activity" className={currentPath==='/event/activity' ? 'active':''}>Activity</Link>
        //             <Link to="/myworks" className={currentPath==='/myworks' ? 'active':''}>MyWorks</Link>
        //             <Link to="/about" className= {currentPath==='/about' ? 'active':''} >About</Link>
        //         </div>
        //     </div>
        // </nav>
        <nav className="navbar navbar-expand-lg navbar-light bg-light">
            <div className="container-fluid">

                {/* Brand/Logo */}
                <Link className="navbar-brand" to="/">Navbar</Link>

                {/* Toggler Button (Hamburger Icon) */}
                <button 
                    className="navbar-toggler" 
                    type="button" 
                    data-bs-toggle="collapse" // BS5: data-bs-toggle
                    data-bs-target="#navbarNavAltMarkup" // BS5: data-bs-target
                    aria-controls="navbarNavAltMarkup" 
                    aria-expanded="false" 
                    aria-label="Toggle navigation"
                >
                    <span className="navbar-toggler-icon"></span>
                </button>

                {/* Collapsible Content */}
                <div className="collapse navbar-collapse" id="navbarNavAltMarkup">
                    <div className="navbar-nav">

                        {/* Home Link: Active if currentPath is '/' */}
                        <Link 
                            className={`nav-item nav-link ${currentPath === '/' ? 'active' : ''}`} 
                            to="/"
                        >
                            Home
                            {/* sr-only is replaced by visually-hidden in BS5 */}
                            <span className="visually-hidden">(current)</span>
                        </Link>

                        {/* Features Link */}
                        <Link 
                            className="nav-item nav-link" 
                            to="/features"
                        >
                            Features
                        </Link>

                        {/* Pricing Link */}
                        <Link 
                            className="nav-item nav-link" 
                            to="/pricing"
                        >
                            Pricing
                        </Link>

                        {/* Disabled Link */}
                        <Link 
                            className="nav-item nav-link disabled" 
                            to="#" 
                            tabIndex="-1" 
                            aria-disabled="true"
                        >
                            Disabled
                        </Link>

                    </div>
                </div>
            </div>
        </nav>
    );
}

export default NavBar;
